-- Lieux nommés et trajets des porteurs fantômes (coordonnées approximatives des stations).

on conflict (name) do update set pos = excluded.pos;

on conflict (name) do update set stops = excluded.stops;

-- Réserve de fantômes répartis sur les trajets ; game_tick() en active
-- autant que nécessaire (voir ghost_target_count()).
select r.id, floor(random() * array_length(r.stops, 1))::int, (array[-1, 1])[1 + floor(random() * 2)::int]
  from public.ghost_routes r, generate_series(1, 10);
